import React from 'react';

// Web-only stub for `react-native-maps` (see metro.config.js).
// The native map stack is not available in browsers; every component here
// renders nothing so screens degrade gracefully instead of crashing the
// whole web bundle at module load.
const Noop = () => null;

export default Noop;
export const Marker = Noop;
export const Polyline = Noop;
export const Polygon = Noop;
export const Circle = Noop;
export const UrlTile = Noop;
export const Overlay = Noop;
export const Callout = Noop;
export const PROVIDER_GOOGLE = null;
export const PROVIDER_DEFAULT = null;
